import sys

def calculate_balanced_triples(n, k, skill_levels, changes):
    skill_tree = [list(range(skill_levels[0], skill_levels[-1] + 1))]

    # Add subsequent skill levels to the skill tree
    for i in range(1, n):
        if skill_levels[i - 1] + 1 < skill_levels[i]:
            skill_tree.append([skill_levels[i - 1] + 1])
            skill_tree.append(list(range(skill_levels[i - 1] + 2, skill_levels[i] + 1)))
        else:
            skill_tree.append(list(range(skill_levels[i - 1] + 2, skill_levels[i] + 1)))

    prefix_sums = {0: 0}
    for elements in skill_tree:
        previous = 0
        for element in elements:
            prefix_sums[element] = previous + len(elements)
            previous = prefix_sums[element]

    balanced_triples = 0

    for _ in range(k):
        ai, bi = map(int, input().split())
        if bi in prefix_sums:
            balanced_numbers = set(skill_levels[ai-1:bi])
            for number in balanced_numbers:
                if number - (bi - 1) in prefix_sums and number - ai in prefix_sums:
                    balanced_triples += prefix_sums[number - bi]
                    balanced_triples -= prefix_sums[number - ai]

    return balanced_triples

