def factorial_mod(n, mod=998244353):
    ans = 1
    for i in range(1, n+1):
        ans = ans * i % mod
    return ans % mod

def binom_mod(n, k, mod=998244353):
    return factorial_mod(reduce(lambda a, j: a * (k-j), range(k+1)) // factorial_mod(k, mod), mod)

def hankel_matrix_mod(m, n, base=10, mod=998244353):
    return pow(base, m * (m - 1) // 2, mod)

def count_possible_arrys(n, a, cache=None):
    if cache is None:
        cache = {}

    ans = 0
    for mask in range(1, pow(2, n)):
        value = factorial_mod(n) // binom_mod(n, binom_mod(n, 1, mod=mod), mod)  # Count of different masks (without vectors)
        cache[mask] = value

    if n == 1:
        return value
    if n == 2:
        return hankel_matrix_mod(value, cache[mask])

    for i in range(1, pow(2, n)):
        is_it = True
        for j in range(n-1):
            if i & (1 << j):
                if (a[j] == a[j+1]) or j == n-2:
                    is_it = False
        if is_it:
            ans += value

