def prime_factors(n):
    i = 2
    factors = []
    while i * i <= n:
        if n % i:
            i += 1
        else:
            n //= i
            factors.append(i)
    if n > 1:
        factors.append(n)
    return factors

def minimum_prime_divisor(price):
    prime_factors_set = set(prime_factors(price | (1 << 31)))
    return next(filter(lambda x: x <= 100, prime_factors_set), -1)

def process_recipe(index, di, pattern, price, prefix):
    if prefix == pattern * di:
        return min(prefix, price | (1 << 31)) if index == 0 else 0
    candidate_prices = []
    for i in range(di):
        if chr(ord('A') + i) in pattern:
            factor = min(price[i], 2**(ord(chr(ord('A') + i)) - ord('A')))
        else:
            factor = min(price[i], di - 2**(ord(chr(ord('A') + i)) - ord('0')))
        candidate_prices.append(prefix + chr(ord('A') + i) * factor)
    candidates = [prefix, *candidate_prices]
    return reduce(min, map(minimum_prime_divisor, map(int, candidates)))

