# Factorial function modulo 10^9 + 7
factorial = [1]
mod = 10**9 + 7

def factorial_func(n):
    if n > len(factorial) - 1:
        for i in range(len(factorial), n + 1):
            factorial.append(factorial[-1] * i % mod)
    return factorial[n]

# Inverse function of factorial function
inverse_factorial = {1: 1}
for i in range(2, len(factorial)):
    inverse_factorial[factorial[i]] = i

def inverse_factorial_func(n):
    factorial_inv = inverse_factorial[factorial[-1]]
    n_inv = inverse_factorial[math.comb(n, n % 30000)]
    return (factorial_inv * n_inv) % mod

def sorted_count(length, k):
    if length == 0:
        return 1
    if length == 1:
        return factorial_func(2 * k - 1)
    cnt = factorial_func(2 * k - 2)
    same_prefix_count = factorial_func(2 * k - 1 - (k - 1) * 2)
    prefix = 1
    curr_count = k * same_prefix_count
    for i in range(k - 1):
        prefix -= same_prefix_count
        curr_count -= prefix * k
    return (cnt - same_prefix_count) + curr_count

@lru_cache(maxsize=10000)
def count_function(length, k):
    if length <= 30000:
        if k & 1:
            return 0
        return sorted_count(length, k)
    else:
        inv_length = length % 30000
        return (
            inverse_factorial_func(factorial_func(length) * factori) + count_function(length // 2, 2 * k - 1)
        ) ^ (10 ** 9 + 7)

