def modulo_power(base, exponent, modulo):
    result = 1
    while exponent > 0:
        if exponent % 2 == 1:
            result = (result * base) % modulo
        base = (base * base) % modulo
        exponent //= 2
    return result

def topological_alternating_paths(n, c_colors, p_odd):
    unordered_paths = 0
    ordered_paths = 0
    mod = 1000000007

    if p_odd:
        for path in itertools.product(range(0, n + 1), range(1, n + 1)):
            if sorted(path) == list(range(1, n + 1)):
                unordered_paths = (unordered_paths + 1) % mod
                if len(path) % 2 == 0:
                    ordered_paths = (ordered_paths + 1) % mod
            elif sorted(path) == list(range(n, 0, -1)):
                unordered_paths = (unordered_paths + 1) % mod
                if len(path) % 2 == 1:
                    ordered_paths = (ordered_paths + 1) % mod
    else:
        for path in itertools.product(range(0, n + 1), range(1, n + 1)):
            if sorted(path) == list(range(1, n + 1)):
                unordered_paths = (unordered_paths + 1) % mod
                if len(path) % 2 == 0:
                    ordered_paths = (ordered_paths + 1) % mod
            elif sorted(path) == list(range(n, 0, -1)):
                unordered_paths = (unordered_paths + 1) % mod
                if len(path) % 2 == 1:
                    ordered_paths = (ordered_paths + 1) % mod

    return (unordered_paths * modulo_power(2, n, mod)) % mod

