# Function to perform path compression and hierarchy distance computation
class DisjointSetForest:
    def __init__(self, n):
        self.parent = list(range(n))
        self.ranks = [0] * n

    def union(self, u, v):
        pv = self.find(u)
        pvv = self.find(v)
        if pv == pvv:
            return
        if self.ranks[pv] < self.ranks[pvv]:
            self.parent[pv] = pvv
        elif self.ranks[pv] > self.ranks[pvv]:
            self.parent[pvv] = pv
        else:
            self.parent[pvv] = pv
            self.ranks[pv] += 1

    def find(self, u):
        path = []
        while self.parent[u] != u:
            path.append(self.parent[u])
            u = self.parent[u]
        # Reconstruct path
        for u in path[::-1]:
            self.parent[u] = u
        return u

def compute_disjoint_set_tree(railroads):
    n = len(railroads) + 1
    disjoint_set = DisjointSetForest(n)
    level = 0
    for i in range(1, n):
        u, v, _ = railroads[i-1]
        if u < v:
            disjoint_set.union(u, v)
        else:
            disjoint_set.union(v, u)
            level += 1
    return n, level

def shortest_path_to_station(railroads, switch_changes, t, level, target_station):
    if level == 1:
        # If the station is a leaf, we need to switch the switch
        return min(level-1, len(switch_changes) - t % len(switch_changes))
    else:
        # Use binary search to find the minimum number of changes needed
        start, end = 0, len(switch_changes) - 1
        while start + 1 < end:
            mid = (start + end) // 2
            if is_possible_with_switch_changes(switch_changes[:mid], t, level-1):
                end = mid
            else:
                start = mid
        return start if is_possible_with_switch_changes(switch_changes[:start], t, level-1) else end

def is_possible_with_switch_changes(switch_changes, t, level, target_station=0):
    if level == 1:
